/* * @lc app=leetcode id=1298 lang=kotlin * * [1298] Maximum Candies You Can Get from Boxes */ class Solution { fun maxCandies(status: IntArray, candies: IntArray, keys: Array<IntArray>, containedBoxes: Array<IntArray>, initialBoxes: IntArray): Int = BooleanArray(status.size).let { hasBox -> BooleanArray(status.size).let { opened -> ArrayDeque<Int>().apply { initialBoxes.forEach { b -> hasBox[b] = true.also { if (status[b] == 1) add(b) } } }.let { q -> generateSequence { if (q.isNotEmpty()) q.removeFirst() else null }.fold(0) { total, b -> if (opened[b]) total else (total + candies[b]).also { opened[b] = true }.also { keys[b].forEach { k -> status[k] = 1.also { if (hasBox[k] && !opened[k]) q.add(k) } } }.also { containedBoxes[b].forEach { cb -> hasBox[cb] = true.also { if (status[cb] == 1 && !opened[cb]) q.add(cb) } } } } } } } }